1	export type Cell = [number, number];
2	
3	function keyOf([x, y]: Cell): string {
4	  return `${x},${y}`;
5	}
6	
7	function neighborsOf([x, y]: Cell): Cell[] {
8	  const offsets = [-1, 0, 1];
9	  return offsets.flatMap((dx) =>
10	    offsets
11	      .filter((dy) => !(dx === 0 && dy === 0))
12	      .map((dy): Cell => [x + dx, y + dy]),
13	  );
14	}
15	
16	function countLiveNeighbors(cell: Cell, liveKeys: Set<string>): number {
17	  return neighborsOf(cell).filter((neighbor) => liveKeys.has(keyOf(neighbor)))
18	    .length;
19	}
20	
21	function willBeAlive(isAlive: boolean, liveNeighborCount: number): boolean {
22	  return isAlive
23	    ? liveNeighborCount === 2 || liveNeighborCount === 3
24	    : liveNeighborCount === 3;
25	}
26	
27	export function nextGeneration(liveCells: Cell[]): Cell[] {
28	  const liveKeys = new Set(liveCells.map(keyOf));
29	  const candidates = new Map<string, Cell>(
30	    [...liveCells, ...liveCells.flatMap(neighborsOf)].map((cell) => [
31	      keyOf(cell),
32	      cell,
33	    ]),
34	  );
35	  return [...candidates.values()].filter((cell) =>
36	    willBeAlive(liveKeys.has(keyOf(cell)), countLiveNeighbors(cell, liveKeys)),
37	  );
38	}
