1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	const sorted = (cells: Cell[]): Cell[] =>
5	  [...cells].sort(([x1, y1], [x2, y2]) => x1 - x2 || y1 - y2);
6	
7	describe("Game of Life - Next Generation", () => {
8	  it("returns an empty grid for an empty grid — [] → []", () => {
9	    expect(nextGeneration([])).toEqual([]);
10	  });
11	  it("kills a single live cell with no neighbors — [(0,0)] → []", () => {
12	    expect(nextGeneration([[0, 0]])).toEqual([]);
13	  });
14	  it("Rule 1 Underpopulation: kills two adjacent cells, each with 1 neighbor — [(0,1), (1,1)] → []", () => {
15	    expect(
16	      nextGeneration([
17	        [0, 1],
18	        [1, 1],
19	      ]),
20	    ).toEqual([]);
21	  });
22	  it("Rule 2 Survival: a live cell with 2 live neighbors lives on — in [(0,0), (1,0), (2,0), (1,2)] the cell (1,0) survives", () => {
23	    expect(
24	      nextGeneration([
25	        [0, 0],
26	        [1, 0],
27	        [2, 0],
28	        [1, 2],
29	      ]),
30	    ).toContainEqual([1, 0]);
31	  });
32	  it("Rule 3 Overpopulation: a live cell with 4 live neighbors dies — in [(0,0), (1,0), (2,0), (1,1), (0,2), (1,2), (2,2)] the center (1,1) dies", () => {
33	    expect(
34	      nextGeneration([
35	        [0, 0],
36	        [1, 0],
37	        [2, 0],
38	        [1, 1],
39	        [0, 2],
40	        [1, 2],
41	        [2, 2],
42	      ]),
43	    ).not.toContainEqual([1, 1]);
44	  });
45	  it("Rule 4 Reproduction: a dead cell with exactly 3 live neighbors becomes alive — [(0,0), (1,0), (0,1)] → includes (1,1)", () => {
46	    expect(
47	      nextGeneration([
48	        [0, 0],
49	        [1, 0],
50	        [0, 1],
51	      ]),
52	    ).toContainEqual([1, 1]);
53	  });
54	  it("Block still life: [(0,0), (1,0), (0,1), (1,1)] stays unchanged", () => {
55	    const block: Cell[] = [
56	      [0, 0],
57	      [1, 0],
58	      [0, 1],
59	      [1, 1],
60	    ];
61	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
62	  });
63	  it("Blinker gen 0 → gen 1: [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]", () => {
64	    const verticalBlinker: Cell[] = [
65	      [0, 0],
66	      [0, 1],
67	      [0, 2],
68	    ];
69	    const horizontalBlinker: Cell[] = [
70	      [-1, 1],
71	      [0, 1],
72	      [1, 1],
73	    ];
74	    expect(sorted(nextGeneration(verticalBlinker))).toEqual(
75	      sorted(horizontalBlinker),
76	    );
77	  });
78	  it("Blinker gen 1 → gen 2: [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]", () => {
79	    const horizontalBlinker: Cell[] = [
80	      [-1, 1],
81	      [0, 1],
82	      [1, 1],
83	    ];
84	    const verticalBlinker: Cell[] = [
85	      [0, 0],
86	      [0, 1],
87	      [0, 2],
88	    ];
89	    expect(sorted(nextGeneration(horizontalBlinker))).toEqual(
90	      sorted(verticalBlinker),
91	    );
92	  });
93	  it("handles negative coordinates — block at [(-2,-2), (-1,-2), (-2,-1), (-1,-1)] stays unchanged", () => {
94	    const negativeBlock: Cell[] = [
95	      [-2, -2],
96	      [-1, -2],
97	      [-2, -1],
98	      [-1, -1],
99	    ];
100	    expect(sorted(nextGeneration(negativeBlock))).toEqual(sorted(negativeBlock));
101	  });
102	});
